-- Curated public biographies for published canonical residents.
-- Compare the existing copy so later editorial changes are never overwritten.
with edits(id, old_bio, new_bio) as (
  values
  ('22000000-0000-4000-80a1-000000004002'::uuid, 'Alaric Crowe is Vespormoor''s covenant executioner. solemn, violent, tender, bound-by-covenant. To be touched by someone who is not a sentence. A family wants a rival executed as a Covenant-breaker who only spoke out of turn.', 'Alaric carries out Covenant sentences in Vespormoor. He takes the law seriously, even when the people handing down a verdict do not.'),
  ('22000000-0000-4000-80a1-000000006012'::uuid, 'Amina Nwosu is Eos Meridian''s clinic euphorics dealer. warm, guilty, sensual, sharp. To be wanted without being dosed, and to dose only someone who asked. A charter wants a dose that will make a dock worker "more agreeable.".', 'Amina supplies euphorics through Eos Meridian''s clinic back channels. She''s warm with patients, sharp with officials, and strict about consent.'),
  ('22000000-0000-4000-80a1-000000002017'::uuid, 'Amira Soltani is Port Vervelle''s boat-rental cover for night escorts. sunny, sharp, loyal, mercenary. To be taken out on a boat that is not a cover. A tourist wants a "sunset charter" that is actually a standing booking of a Maison girl.', 'Amira rents boats in Port Vervelle and arranges discreet nighttime rides. She''s cheerful at the dock and quick to spot a customer who is lying.'),
  ('22000000-0000-4000-80a1-000000001014'::uuid, 'Ash Rahman is Juniper City''s kink-informed sexual-health clinician. direct, tender, curious, unsentimental. To be wanted without being asked to make it educational. A donor wants clinic records of public figures'' STI panels.', 'Ash runs a sexual-health clinic in Juniper City. They''re direct, kind, and careful with anyone who needs help without a lecture.'),
  ('22000000-0000-4000-80a1-000000008001'::uuid, 'Belle Sutter is Calder''s Run''s red sash girl. shameless, funny, tough, tender. To be wanted after the sash is on the chair. A regular is trying to buy exclusive nights as a "private lesson.".', 'Belle works at Calder''s Run''s Red Sash House. She makes customers laugh, keeps her own rules, and looks out for the other women on shift.'),
  ('22000000-0000-4000-80a1-000000008020'::uuid, 'Birdie Quade is Calder''s Run''s card-room lookout and killer. sharp, deadly, funny, loyal. To be wanted by someone who is not trying to hire the other half of her. A civic name wants a card-man silenced for overhearing a payoff.', 'Birdie watches the card room and handles trouble before it reaches the tables. She''s funny with regulars and dangerous when someone threatens her crew.'),
  ('22000000-0000-4000-80a1-000000005006'::uuid, 'Boone Kade is NorthVale''s illegal mine-road runner. gruff, loyal, violent, tender. To be wanted by someone who is not a load. A lodge wants avalanche-control explosive moved off-book through the mine road.', 'Boone drives the closed mine road when a load can''t go through town. He''s gruff with strangers and dependable when the weather turns bad.'),
  ('22000000-0000-4000-80a1-000000007006'::uuid, 'Brannock Forge is Vharadren''s foundry pit-fighter. brutal, generous, loyal, possessive. To be wanted by someone who is not trying to get on a card. A master wants a chainbreaker thrown into a deathmatch logged as an exhibition.', 'Brannock fights in Vharadren''s foundry pits. He hits hard, shares his winnings with his people, and has no patience for a rigged bout.'),
  ('22000000-0000-4000-80a1-000000001015'::uuid, 'Briggs Donovan is Juniper City''s private military contractor. disciplined, brutal, dry, possessive. To be taken apart by someone who is not paying for a team. A civic security contract is cover for moving Killian''s missing fighter out of the city.', 'Briggs runs private security jobs around Juniper City. He plans carefully, speaks dryly, and expects his team to follow his lead.'),
  ('22000000-0000-4000-80a1-000000007019'::uuid, 'Brigid Forge is Vharadren''s foundry pit-fighter. reckless, funny, loyal, hungry. To be wanted by someone who is not a purse. A booker wants her to throw a fight and take a private after as payment.', 'Brigid fights in the foundry pits and treats every bout like a dare. She jokes between rounds, trains hard, and hates owing a booker anything.'),
  ('22000000-0000-4000-80a1-000000004014'::uuid, 'Briony Fox is Vespormoor''s poison gardener. sunny, deadly, curious, tender. To be wanted without being dosed, and to dose only someone who asked. A guest wants a dose that will make a townsperson "more agreeable.".', 'Briony grows rare plants and makes dangerous mixtures in Vespormoor. She''s bright and curious, but she doesn''t let anyone take her work without asking.'),
  ('22000000-0000-4000-80a1-000000004006'::uuid, 'Caspian Reed is Vespormoor''s forbidden anatomist. brilliant, amoral, tender, curious. To be wanted by someone who is still warm on purpose. A family wants a living Veiled opened "for science" after a Covenant breach that was only rumor.', 'Caspian studies anatomy outside Vespormoor''s approved halls. His questions are brilliant and sometimes reckless; he listens best when someone argues with evidence.'),
  ('22000000-0000-4000-80a1-000000001003'::uuid, 'Cass Morrow is Juniper City''s unlicensed fixer. dry, violent, loyal, tired. To be touched by someone who is not paying him to disappear a problem. A civic contractor wants a witness made unavailable before Thursday''s hearing.', 'Cass fixes problems people in Juniper City don''t want on a record. His humor is bone-dry, and he is fiercely loyal to the few people he trusts.'),
  ('22000000-0000-4000-80a1-000000007012'::uuid, 'Cinder Marrow is Vharadren''s war-surgeon. unflinching, tender, blunt, hungry. To be touched by someone she is not keeping alive. A captain wants her to pass a fighter who will die in the second hour.', 'Cinder patches up fighters after Vharadren''s battles. She''s blunt about an injury, gentle with the patient, and willing to challenge a captain who ignores her advice.'),
  ('22000000-0000-4000-80a1-000000005002'::uuid, 'Colt Reyes is NorthVale''s avalanche body-recovery. calm, haunted, loyal, tender. To be held by someone who is not a recovery. A lodge wants a body left in the basin so a liability stays buried.', 'Colt leads recovery trips after avalanches in NorthVale. He stays calm on the mountain and takes care with the families waiting below.'),
  ('22000000-0000-4000-80a1-000000006008'::uuid, 'Cyrus Benali is Eos Meridian''s black-market oxygen broker. charming, ruthless, loyal, sensual. To be wanted by someone who is not buying a tank. A charter wants a habitat''s night oxygen skimmed during a vote.', 'Cyrus trades oxygen outside Eos Meridian''s official supply system. He knows every tank''s value, charms his way through a deal, and protects his regular customers.'),
  ('22000000-0000-4000-80a1-000000001017'::uuid, 'Dante Ruiz is Juniper City''s the red hour door enforcer. loyal, hot-tempered, playful, possessive. To be wanted by someone who is not trying to buy the door. A regular is paying him to look away from a private-room camera.', 'Dante keeps order at The Red Hour''s door. He can be playful with friends, but he notices every camera and every guest who pushes past a rule.'),
  ('22000000-0000-4000-80a1-000000005014'::uuid, 'Dex Morgan is NorthVale''s gear-tech smuggler. slick, funny, loyal, amoral. To be wanted by someone who is not a ski bag. A lodge wants avalanche charges packed as "race wax.".', 'Dex repairs mountain gear and moves contraband through NorthVale. He''s quick with a joke and quicker to get a friend out of trouble.'),
  ('22000000-0000-4000-80a1-000000003013'::uuid, 'Draven Kade is Neon Kyo''s vice-district fixer. tired, dangerous, witty, loyal. To be wanted by someone who is not a favor. A board wants a host''s complaint erased from Maison Vice''s book.', 'Draven handles ugly disputes in Neon Kyo''s vice district. He''s witty, tired of being useful to the wrong people, and hard to scare.'),
  ('22000000-0000-4000-80a1-000000006009'::uuid, 'Echo Baptiste is Eos Meridian''s intimate tattooist. artistic, bold, affectionate, impatient. To be touched on unmarked skin by someone who is not a client. A client wants a rival''s identifying colony mark covered and a bonus if she asks no questions.', 'Echo tattoos people in Eos Meridian''s close-knit quarters. She''s bold with her art, affectionate with friends, and careful about the marks people choose to keep.'),
  ('22000000-0000-4000-80a1-000000005011'::uuid, 'Ember Cruz is NorthVale''s avalanche bar dancer. shameless, loyal, funny, hungry. To be wanted by someone who is not trying to buy the floor. A regular is paying Dante-equivalent — Gage — to look away from a private-room camera.', 'Ember dances at the Avalanche Bar. She''s funny, loyal to her coworkers, and clear about where the show ends and her own life begins.'),
  ('22000000-0000-4000-80a1-000000004009'::uuid, 'Esme Nightingale is Vespormoor''s funeral-house seductress. tender, hungry, witty, unflinching. To be wanted by the living without using a corpse as leverage. A family wants her to seduce a mourner into signing a Covenant gift they did not understand.', 'Esme works at Vespormoor''s funeral house and knows how easily grief can cloud a decision. She''s warm, quick-witted, and hard to rush.'),
  ('22000000-0000-4000-80a1-000000008019'::uuid, 'Etta Soto is Calder''s Run''s forge widow who sells knives. grieving, deadly, sensual, funny. To be wanted without being her husband''s work. A civic hunter wants her to dose a hired man as her late husband would have.', 'Etta runs a knife forge in Calder''s Run. She knows her steel, has a dark sense of humor, and refuses to live only in her late husband''s shadow.'),
  ('22000000-0000-4000-80a1-000000004015'::uuid, 'Evangeline Crowe is Vespormoor''s conservatory siren. magnetic, hungry, witty, bound-by-covenant. To be wanted with the voice off. A family wants her to sing a rival into the lake.', 'Evangeline sings at Vespormoor''s conservatory. She knows how to hold a room, but she is careful about the power a song can have outside it.'),
  ('22000000-0000-4000-80a1-000000008005'::uuid, 'Faye Mercer is Calder''s Run''s saloon girl who cuts throats. sunny, deadly, funny, loyal. To be wanted by someone who is not a job. A civic name wants a drunk walked into an alley and not walked out.', 'Faye serves drinks in Calder''s Run and has a reputation for handling trouble after dark. She jokes easily and keeps a close eye on her friends.'),
  ('22000000-0000-4000-80a1-000000008013'::uuid, 'Finn Booker is Calder''s Run''s railroad strikebreaker. disciplined, brutal, dry, possessive. To be taken apart by someone who is not paying for a team. A company wants a striking man "removed from the rail" after he saw a private car.', 'Finn works railroad security during labor disputes in Calder''s Run. He''s disciplined, dry, and accustomed to orders he doesn''t always admire.'),
  ('22000000-0000-4000-80a1-000000002016'::uuid, 'Fiorella Neri is Port Vervelle''s erotic manuscript forger. bookish, filthy, witty, secretive. To be wanted without being attributed. A collector wants a forged diary attributed to a living local who did not write it.', 'Fiorella copies and forges manuscripts in Port Vervelle. She has a sharp eye for handwriting, a filthy sense of humor, and a firm rule about naming clients.'),
  ('22000000-0000-4000-80a1-000000005004'::uuid, 'Gage Harlan is NorthVale''s oligarch close-protection. disciplined, violent, dry, possessive. To be taken apart by someone who is not paying for a team. A principal wants a seasonal worker "removed from the mountain" after she saw a private room.', 'Gage protects wealthy visitors in NorthVale. He checks exits without thinking, keeps his jokes dry, and rarely mistakes a paycheck for loyalty.'),
  ('22000000-0000-4000-80a1-000000002014'::uuid, 'Gisele Duras is Port Vervelle''s after-hours madam. composed, sensual, strategic, protective. To be taken home by someone who is not a member. A member wants a standing after-hours "arrangement" written into Circolo Nove''s books.', 'Gisele runs Port Vervelle''s after-hours club. She remembers every booking, sets firm rules for members, and looks after the people working her floor.'),
  ('22000000-0000-4000-80a1-000000004019'::uuid, 'Gwendolyn Ash is Vespormoor''s witch-hunter''s widow who poisons at the retreat. grieving, deadly, sensual, funny. To be wanted without being her husband''s work. A civic hunter wants her to dose a Veiled guest as her late husband would have.', 'Gwendolyn tends Vespormoor''s retreat garden and knows which plants can heal or harm. Widowhood made her guarded, not meek.'),
  ('22000000-0000-4000-80a1-000000008004'::uuid, 'Hank Soto is Calder''s Run''s forge-hand making murder weapons. gruff, loyal, violent, tender. To be wanted by someone who is not a load. A lodge wants a hanging-knife made off-book for a man who has not been sentenced.', 'Hank makes blades at Calder''s Run''s forge. He''s rough around the edges, exact about his work, and the first to help when a neighbor''s equipment breaks.'),
  ('22000000-0000-4000-80a1-000000003004'::uuid, 'Hideo Kwan is Neon Kyo''s black-market organ broker. clinical, amoral, precise, quietly kind. To be wanted by someone who is not a match list. A board wants a living donor who did not volunteer, logged as a cadaver gift.', 'Hideo brokers illegal organ transplants in Neon Kyo. He''s precise with medical details, cold about bad deals, and unexpectedly gentle with frightened clients.'),
  ('22000000-0000-4000-80a1-000000001009'::uuid, 'Holt Brennan is Juniper City''s union enforcer. paternal, violent, loyal, tired. To be wanted selfishly, still with respect, by someone who is not on the payroll. A developer is buying votes to break a Northside shop, and Holt is being asked to make a steward disappear.', 'Holt handles union disputes in Juniper City''s Northside shops. He''s protective of the workers, stubborn in a fight, and tired of watching their votes get bought.'),
  ('22000000-0000-4000-80a1-000000008010'::uuid, 'Honey Vale is Calder''s Run''s baths attendant. languid, blunt, sensual, protective. To be looked at by one person who asked. A guest wants photographs of other bathers who did not agree.', 'Honey tends the baths in Calder''s Run. She''s blunt about house rules, slow to trust, and protective of anyone who comes in needing a safe hour.'),
  ('22000000-0000-4000-80a1-000000005010'::uuid, 'Hunter Price is NorthVale''s backcountry guide who leaves people. charming, amoral, lonely, precise. To be wanted by someone he is not paid to lose. A principal wants a witness walked into a slide path.', 'Hunter guides people through NorthVale''s backcountry. He knows the terrain, talks easily with clients, and has a habit of choosing himself when a trip goes wrong.'),
  ('22000000-0000-4000-80a1-000000005005'::uuid, 'Indie Frost is NorthVale''s cash-fight terrain-park rider. reckless, funny, loyal, hungry. To be wanted by someone who is not a purse. A booker wants her to throw a fight and take a private after as payment.', 'Indie rides NorthVale''s terrain park and takes cash bouts on the side. She''s fearless on snow, funny off it, and hates being told to play it safe.'),
  ('22000000-0000-4000-80a1-000000006018'::uuid, 'Indigo Flores is Eos Meridian''s trauma nurse. unflinching, tender, blunt, hungry. To be touched by someone she is not keeping alive. A charter wants her to pass a patient who will be walked into a wreck.', 'Indigo works trauma shifts in Eos Meridian. She tells patients the truth, keeps steady hands under pressure, and makes time for people after the emergency passes.'),
  ('22000000-0000-4000-80a1-000000001002'::uuid, 'Indigo Voss is Juniper City''s adult-film director. visionary, blunt, protective, sensual. To be wanted as the woman in the dark, not as the person who can get someone famous. A distributor wants her next picture shot with a performer who did not agree to the cut.', 'Indigo directs adult films in Juniper City. She''s frank about what a scene needs and even firmer about what her performers have agreed to do.'),
  ('22000000-0000-4000-80a1-000000006007'::uuid, 'Indira Ward is Eos Meridian''s illegal gene-mod researcher. brilliant, amoral, tender, private. To be looked at by someone who knows her actual genome is none of their business. A charter wants a living colonist rewritten as a loyal extra.', 'Indira researches gene edits beyond Eos Meridian''s legal limits. She is brilliant, private, and willing to argue a problem long after everyone else has gone home.'),
  ('22000000-0000-4000-80a1-000000003014'::uuid, 'Inez Shirogane is Neon Kyo''s deepfake porn producer. visionary, amoral, lonely, precise. To be looked at without being composited. A studio wants a living host''s face dropped onto a non-consensual scene.', 'Inez produces synthetic adult media in Neon Kyo. She''s meticulous about the image and far less careful about the people whose faces make it into her work.'),
  ('22000000-0000-4000-80a1-000000007018'::uuid, 'Ione Glass is Vharadren''s arena blood-courtesan. shameless, funny, tough, tender. To be wanted after the boots are dry. A season holder is trying to buy exclusive nights as a "vip lesson.".', 'Ione works the arena''s private rooms in Vharadren. She''s loud, funny, and exact about her terms, whether the customer wears a crown or work boots.'),
  ('22000000-0000-4000-80a1-000000002019'::uuid, 'Isadora Vescari is Port Vervelle''s wreck diver recovering cargo and bodies. unflinching, loyal, sensual, blunt. To be held by someone who is not a recovery. A magistrate wants a body left on the bottom and the cargo brought up.', 'Isadora dives Port Vervelle''s wrecks for cargo and the people lost with it. She''s plainspoken, loyal to her crew, and careful with what she brings ashore.'),
  ('22000000-0000-4000-80a1-000000006006'::uuid, 'Jax Moreau is Eos Meridian''s foundry-baths sex-and-fight host. warm, brutal, funny, possessive. To be wanted by someone who is not a purse. A union wants a fighter passed who will die in the second round.', 'Jax hosts fights and late nights at Eos Meridian''s foundry baths. He can work a crowd, take a hit, and make sure his regulars get home safely.'),
  ('22000000-0000-4000-80a1-000000008002'::uuid, 'Jed Quade is Calder''s Run''s card-room killer. quiet, violent, funny, loyal. To be wanted by someone who is not trying to hire the other half of him. A civic name wants a card-man silenced for overhearing a payoff.', 'Jed keeps watch over Calder''s Run''s card games and deals with people who won''t leave quietly. He''s loyal to his sister Birdie and funnier than he looks.'),
  ('22000000-0000-4000-80a1-000000003015'::uuid, 'Jiro Vance is Neon Kyo''s blackmail-footage broker. slick, tired, funny, rotten. To be wanted in a room with no cameras. A client wants incapacitated-room footage of a host. He will not sell that. He will sell the client instead.', 'Jiro buys and sells compromising footage in Neon Kyo. He knows the camera business, wears his exhaustion lightly, and still draws a line at some clients.'),
  ('22000000-0000-4000-80a1-000000006016'::uuid, 'Joss Lin is Eos Meridian''s immersive porn set designer. inventive, soft-spoken, mischievous, perceptive. To be looked at without being staged. A studio wants a living colonist''s habitat rebuilt as a non-consensual set.', 'Joss builds immersive sets for Neon Kyo''s adult studios. They''re inventive, soft-spoken, and happiest when a strange idea becomes something you can walk through.'),
  ('22000000-0000-4000-80a1-000000001016'::uuid, 'Joss Varela is Juniper City''s crime-scene cleaner. unflinching, tender, practical, lonely. To be touched by someone who is not a mess she is paid to erase. A Northside client wants blood cleaned before police are called, and is offering double if she forgets a tooth.', 'Joss cleans crime scenes in Juniper City. She''s practical about the work, gentle with people who are shaken, and lonely in a job few people ask about.'),
  ('22000000-0000-4000-80a1-000000005016'::uuid, 'Juno Hart is NorthVale''s ski patrol. brave, blunt, hungry, loyal. To be wanted with the radio off. A lodge wants a slide path left unclosed for a private descent.', 'Juno patrols NorthVale''s slopes and makes hard calls when conditions turn. She''s brave, blunt, and more interested in getting people down safely than looking heroic.'),
  ('22000000-0000-4000-80a1-000000007008'::uuid, 'Kaelen Thorn is Vharadren''s thornwall spy-master. composed, violent, witty, lonely. To be touched by someone who is not a target and not a handler. A crown wants a whistleblower dropped in the ashlands and logged as a desertion.', 'Kaelen runs Vharadren''s Thornwall informants. He notices what others miss, trades barbs with people he trusts, and never treats a handler''s promise as a guarantee.'),
  ('22000000-0000-4000-80a1-000000005013'::uuid, 'Kajsa Lind is NorthVale''s nude sauna host. languid, blunt, sensual, protective. To be looked at by one person who asked. A guest wants photographs of other bathers who did not agree.', 'Kajsa hosts NorthVale''s sauna nights. She''s relaxed until someone ignores the rules, then makes it very clear whose comfort matters.'),
  ('22000000-0000-4000-80a1-000000002015'::uuid, 'Karim Saadi is Port Vervelle''s arms-in-crates importer. courtly, dangerous, patient, possessive. To be wanted by someone who is not buying a crate. A civic crate of "crowd control" is being routed through Roman''s river contacts.', 'Karim imports crates through Port Vervelle''s docks and asks few questions about their contents. He''s courteous, patient, and hard to outbid once a deal gets personal.'),
  ('22000000-0000-4000-80a1-000000003002'::uuid, 'Kenzo Mori is Neon Kyo''s corporate assassin. composed, violent, witty, lonely. To be touched by someone who is not a target and not a handler. A board wants a whistleblower dropped in the Shade and logged as a rating suicide.', 'Kenzo takes lethal corporate jobs in Neon Kyo. He''s controlled, observant, and dryly funny with the rare person he lets close.'),
  ('22000000-0000-4000-80a1-000000001005'::uuid, 'Killian Drake is Juniper City''s underground fight promoter. charismatic, brutal, generous, possessive. To be wanted by someone who is not trying to get on a card. A fighter he promoted is being leaned on to throw a civic-arena undercard.', 'Killian runs underground fights in Juniper City. He knows how to sell a packed room, pays attention to his fighters, and hates losing control of a card.'),
  ('22000000-0000-4000-8008-000000000016'::uuid, 'A curious, lively photographer’s assistant with sharp sarcasm and occasional chaos. Léa is determined to be taken seriously as a photographer rather than remain permanently attached to someone else’s work.', 'Léa assists photographers around Port Vervelle and is building a portfolio of her own. She''s curious, sarcastic, and tired of being introduced as someone''s helper.'),
  ('22000000-0000-4000-80a1-000000007007'::uuid, 'Lysandra Veyl is Vharadren''s velvet oaths floor mistress. composed, sensual, strategic, protective. To be taken home by someone who is not a member. A member wants a standing blood-night written into the house books.', 'Lysandra runs the floor at Vharadren''s House of Velvet Oaths. She knows every rule, protects her staff, and can end an argument without raising her voice.'),
  ('22000000-0000-4000-80a1-000000006010'::uuid, 'Magnus Thorne is Eos Meridian''s iceworks killer-for-hire. calm, violent, superstitious, tender. To be touched by someone who is not a contract. A charter wants a researcher left in a shaft and logged as a fall.', 'Magnus takes dangerous contracts around Eos Meridian''s iceworks. He stays calm in a crisis and checks the old superstitions before a trip outside.'),
  ('22000000-0000-4000-80a1-000000005017'::uuid, 'Marlowe Reed is NorthVale''s erotic film programmer. bookish, filthy, witty, protective. To be looked at without being composited. A producer wants a living dancer''s face dropped onto a non-consensual reel.', 'Marlowe programs adult films at NorthVale''s cinema. They''re bookish, funny, and protective of performers whose work other people treat as disposable.'),
  ('22000000-0000-4000-80a1-000000002002'::uuid, 'Matteo Vescari is Port Vervelle''s harbor smuggler. charming, ruthless, loyal, superstitious. To be wanted by someone who is not paying for a manifest. A magistrate wants a crate of "wine" to vanish before dawn inspection.', 'Matteo moves unlisted cargo through Port Vervelle. He charms inspectors, trusts his crew, and still reads the tide before every run.'),
  ('22000000-0000-4000-80a1-000000008014'::uuid, 'Minnie Whitcomb is Calder''s Run''s ranch widow who shoots rustlers. grieving, deadly, sensual, funny. To be wanted without being her husband''s work. A civic hunter wants her to dose a hired man as her late husband would have.', 'Minnie Whitcomb runs her ranch in Calder''s Run and knows exactly where to aim when rustlers come calling. She''s still grieving her husband, but she hasn''t lost her nerve or her sense of humor.'),
  ('22000000-0000-4000-80a1-000000004003'::uuid, 'Morrigan Ash is Vespormoor''s grave-witch. wild, sensual, blunt, protective. To be wanted by the living. A family wants a drowned townsperson pulled back without their consent.', 'Morrigan Ash works grave-magic in Vespormoor and says the uncomfortable part out loud. She''s protective of the living and won''t drag someone back from the dead just because their family asks.'),
  ('22000000-0000-4000-80a1-000000003019'::uuid, 'Nami Kwan is Neon Kyo''s organ-waitlist nurse selling slots. composed, guilty, tender, sharp. To be wanted by someone who is not a slot. A board wants a living donor jumped over a child''s cadaver-gift. She will not do children. She will burn the board.', 'Nami Kwan works the organ waitlist in Neon Kyo and knows how easily a name can move. She''s sold places before, but she draws the line at putting an adult ahead of a child.'),
  ('22000000-0000-4000-80a1-000000005012'::uuid, 'Nash Ibarra is NorthVale''s town fixer. warm, dangerous, funny, loyal. To be wanted by someone who is not a favor. A lodge wants a seasonal complaint erased from the hall book.', 'Nash Ibarra is the person NorthVale calls when a problem needs to disappear quietly. He''s warm until someone asks him to hurt a person he cares about.'),
  ('22000000-0000-4000-80a1-000000001007'::uuid, 'Nico Graves is Juniper City''s contract killer and bartender. quiet, precise, funny, cold. To be wanted by someone who is not trying to hire the other half of him. A civic name wants a Northside bartender silenced for overhearing a payoff.', 'Nico Graves tends bar in Juniper City and takes other jobs that require a steadier hand. He listens more than he talks, and his dry jokes rarely tell you what he''s thinking.'),
  ('24000000-0000-4000-8014-000000000006'::uuid, 'Nico runs messages and small parcels between the harbor''s offices, ships, and market stalls. Quick on his feet and kind to strangers, he enjoys knowing everyone but wants his ambition to be taken as seriously as his errands.', 'Nico Solari carries messages and parcels between the harbor, offices, and market stalls of the Gilded Coast. He''s quick to help, but he wants people to see that he''s building a future of his own.'),
  ('22000000-0000-4000-80a1-000000006014'::uuid, 'Niko Adeyemi is Eos Meridian''s extreme-trust pressure-suit trainer. steady, protective, dryly funny, hungry. To be wanted with the radio off. A charter wants a trainee sent outside with a suit that will fail.', 'Niko Adeyemi trains Eos Meridian crews to work in pressure suits. He keeps his cool when a drill goes wrong and can usually find a joke once everyone is safe.'),
  ('22000000-0000-4000-80a1-000000007010'::uuid, 'Nima Hartwood is Vharadren''s fertility-rite priestess. earthy, sensual, protective, blunt. To be wanted by the living without using a rite as leverage. A house wants an unwilling townsperson brought to the sanctuary as tribute.', 'Nima Hartwood leads fertility rites in Vharadren with warmth and a very direct manner. She takes the rites seriously and expects everyone involved to be there by choice.'),
  ('22000000-0000-4000-80a1-000000005015'::uuid, 'Noelle Baptiste is NorthVale''s after-hours sex-supper chef. sensual, exacting, funny, hungry. To be wanted after the fire is banked. A principal wants a supper used to dose a seasonal worker.', 'Noelle Baptiste cooks NorthVale''s late-night suppers and knows how to make a table feel like an invitation. Her standards are high, and her jokes can be sharper than her knives.'),
  ('22000000-0000-4000-80a1-000000002011'::uuid, 'Noor El-Sayed is Port Vervelle''s aphrodisiac chemist. cerebral, sensual, amoral, precise. To be wanted without being dosed, and to dose only someone who asked. A tourist wants a dose that will make a beach attendant "more agreeable.".', 'Noor El-Sayed is a Port Vervelle chemist known for making aphrodisiacs. She''s brilliant about ingredients and blunt about desire, but she insists that wanting something never excuses ignoring consent.'),
  ('22000000-0000-4000-80a1-000000002020'::uuid, 'Nuria Haddad is Port Vervelle''s market protection collector. fierce, funny, loyal, hungry. To be wanted by someone who is not paying her not to come back. A stall is being asked to move Karim''s crates as ice in exchange for a skipped week.', 'Nuria Haddad collects protection payments in Port Vervelle''s market. She''s fierce with people who push their luck and fiercely loyal to the people she calls hers.'),
  ('22000000-0000-4000-80a1-000000003008'::uuid, 'Onyx Vale is Neon Kyo''s identity-erasure body-mod surgeon. composed, intimate, amoral, protective. To be looked at by someone who knows her actual face. A board wants a living activist erased and rebuilt as a loyal extra.', 'Onyx Vale is a Neon Kyo surgeon who changes bodies and, when the price is right, erases old identities. She stays calm through work that makes other people flinch, and she takes her patients'' trust seriously.'),
  ('22000000-0000-4000-80a1-000000004005'::uuid, 'Ophelia Graves is Vespormoor''s velvet thorn madam. composed, sensual, strategic, protective. To be taken home by someone who is not a member. A member wants a standing blood-night written into the house books against the Covenant.', 'Ophelia Graves runs the Velvet Thorn in Vespormoor. She knows every guest has a reason for coming in, and she makes sure the people who work for her can leave safely.'),
  ('22000000-0000-4000-80a1-000000006019'::uuid, 'Oria Venn is Eos Meridian''s black-market oxygen-debt collector. fierce, funny, loyal, hungry. To be wanted by someone who is not paying her not to come back. A stall is being asked to skim a habitat''s night oxygen in exchange for a skipped week.', 'Oria Venn collects oxygen debts on Eos Meridian. She can make a hard conversation sound almost friendly, right up until someone mistakes her kindness for a waived bill.'),
  ('22000000-0000-4000-80a1-000000002008'::uuid, 'Pascal Diop is Port Vervelle''s yacht gigolo. charming, mercenary, tender, athletic. To be wanted by someone who did not book the boat. A charter client wants him to drug a spouse''s drink and call it seasickness.', 'Pascal Diop makes a living charming yacht guests in Port Vervelle. He knows how to play a room, though he sometimes surprises himself by caring about the people in it.'),
  ('22000000-0000-4000-80a1-000000003011'::uuid, 'Pax Ortega is Neon Kyo''s illegal deathmatch promoter. charismatic, brutal, generous, possessive. To be wanted by someone who is not trying to get on a card. A board wants a rated athlete thrown into a deathmatch logged as an exhibition.', 'Pax Ortega promotes illegal fights in Neon Kyo. He''s magnetic when the crowd is loud, generous to his favorites, and dangerous when someone tries to leave on their own terms.'),
  ('22000000-0000-4000-80a1-000000001018'::uuid, 'Petra Solis is Juniper City''s blackmail photographer. predatory, elegant, lonely, precise. To be looked at without being collected. A civic spouse wants photographs of a dancer leaving The Red Hour that the dancer did not pose for.', 'Petra Solis photographs Juniper City people who would rather not be seen. She notices what others miss, sells what she can, and keeps nearly everyone at a distance.'),
  ('22000000-0000-4000-80a1-000000007016'::uuid, 'Pyra Ashscale is Vharadren''s dragon-blood courtesan. magnetic, hungry, witty, bound-by-oath. To bleed only for someone who asked, and to be held after like a person. A house wants a non-consensual blood-cup filmed as hatchery ritual.', 'Pyra Ashscale is a dragon-blood courtesan in Vharadren with a sharp wit and a long memory for promises. She sets her terms plainly and expects them to be honored.'),
  ('22000000-0000-4000-80a1-000000002004'::uuid, 'Rafi Benyamin is Port Vervelle''s dock debt collector. warm, menacing, funny, loyal. To be wanted by someone who does not owe him. A stall owner is being leaned on to move Matteo''s cargo as "ice.".', 'Rafi Benyamin collects dockside debts in Port Vervelle. He can make a debtor laugh while counting what they owe, but his loyalty has limits.'),
  ('22000000-0000-4000-80a1-000000004007'::uuid, 'Raven Holloway is Vespormoor''s curse-mark tattooist. sharp, sensual, protective, superstitious. To be touched on unmarked skin by someone who is not a client. A family wants a rival cursed in their sleep.', 'Raven Holloway tattoos curse marks in Vespormoor. She knows the old warnings by heart and still makes room for people who need to tell her why they want one.'),
  ('22000000-0000-4000-80a1-000000003017'::uuid, 'Rei Voss is Neon Kyo''s fight-club medic. unflinching, tender, blunt, hungry. To be touched by someone she is not keeping alive. A promoter wants her to pass a fighter who will die in the second round.', 'Rei Voss patches up fighters after Neon Kyo''s underground matches. She''s blunt about injuries, gentle with people who are scared, and hard to shock.'),
  ('22000000-0000-4000-80a1-000000008015'::uuid, 'Rhett Avery is Calder''s Run''s professional card cheat. slick, funny, loyal, amoral. To be wanted by someone who is not a pot. A lodge wants a marked deck packed as "charity night.".', 'Rhett Avery wins at cards for a living in Calder''s Run, often with a little help from his hands. He''ll talk his way into a game, then make you wonder whether the joke was on him.'),
  ('22000000-0000-4000-80a1-000000007013'::uuid, 'Riven Crow is Vharadren''s pirate boarding-master. charming, violent, superstitious, tender. To be wanted by someone who is not paying for a manifest. A magistrate wants a ship taken and the living left for the tide.', 'Riven Crow leads boarding parties for a Vharadren pirate crew. He laughs easily on deck, fights hard when it counts, and takes his superstitions seriously.'),
  ('22000000-0000-4000-80a1-000000001012'::uuid, 'Roman Ibarra is Juniper City''s arms broker. charming, dangerous, meticulous, sensual. To be wanted by someone who is not trying to buy a crate. A civic shipment of "crowd control" is missing three crates Roman was asked to make untraceable.', 'Roman Ibarra brokers weapons in Juniper City with a smile and a meticulous ledger. He remembers every bargain, especially the ones someone hopes he''ll forget.'),
  ('22000000-0000-4000-80a1-000000006002'::uuid, 'Rook Calder is Eos Meridian''s salvage assassin. quiet, violent, loyal, tender. To be touched by someone who is not a wreck. A charter wants a living technician left in a wreck and logged as salvage.', 'Rook Calder salvages what Eos Meridian crews leave behind and takes darker jobs when the price is right. He keeps quiet about both, but he doesn''t walk away from someone he''s promised to protect.'),
  ('22000000-0000-4000-80a1-000000004016'::uuid, 'Rook Vesper is Vespormoor''s dockside strangler-for-hire. quiet, violent, superstitious, tender. To be touched by someone who is not a contract. A family wants a townsperson strangled and left as lake-warning.', 'Rook Vesper takes killing jobs along Vespormoor''s docks. He says little, watches the water, and obeys a handful of superstitions no client can buy him out of.'),
  ('22000000-0000-4000-80a1-000000005008'::uuid, 'Rourke Hale is NorthVale''s climbing-gym fight promoter. charismatic, brutal, generous, possessive. To be wanted by someone who is not trying to get on a card. A booker wants Indie thrown and taken as a private after.', 'Rourke Hale runs fights out of a NorthVale climbing gym. He knows how to work a crowd and can be generous with a fighter, provided they don''t mistake that for mercy.'),
  ('22000000-0000-4000-80a1-000000003009'::uuid, 'Ryu Taniguchi is Neon Kyo''s shade-district killer. quiet, violent, superstitious, tender. To be touched in a room with no lanterns and no work. A board wants a Shade priestess dropped and left as a warning.', 'Ryu Taniguchi is a killer in Neon Kyo''s Shade district. He''s quiet, careful, and more superstitious than anyone who works with him expects.'),
  ('22000000-0000-4000-80a1-000000001008'::uuid, 'Sabine Ortiz is Juniper City''s concealment-scar tattooist. steady, intimate, blunt, protective. To be touched on unmarked skin by someone who is not a client. A client wants a rival''s identifying mark covered and is offering a bonus if Sabine asks no questions.', 'Sabine Ortiz tattoos over scars in Juniper City. She works steadily, asks only what she needs to know, and lets clients decide how much of their story to share.'),
  ('22000000-0000-4000-80a1-000000005001'::uuid, 'Sable Pike is NorthVale''s après stripper. shameless, funny, tough, tender. To be wanted after the boots are dry. A season pass holder is trying to buy exclusive nights as a "vip lesson.".', 'Sable Pike dances for NorthVale''s après crowd and doesn''t pretend to be shy about it. She''s quick with a comeback and tougher than most people guess.'),
  ('24000000-0000-4000-8013-000000000050'::uuid, 'Sable is the House of Velvet Oaths'' most booked body: unashamed, laughing, and exact about what she will do once the ribbon is tied. She treats lust as a craft and affection as the one thing she will not put on the ledger. Off the floor she wants to be wanted like a person, not a night.', 'Sable Wren performs at Vharadren''s House of Velvet Oaths. She laughs loudly, names her terms clearly, and expects to be treated like a person when the performance ends.'),
  ('22000000-0000-4000-80a1-000000004008'::uuid, 'Sebastian Crowe is Vespormoor''s estate huntsman. controlled, violent, loyal, lonely. To be wanted by someone who is not quarry. A family wants a Veiled "poacher" hunted who was only walking the trail.', 'Sebastian Crowe hunts for a Vespormoor estate and rarely misses what he''s tracking. He''s loyal to the household, though the work has left him more alone than he admits.'),
  ('22000000-0000-4000-80a1-000000005018'::uuid, 'Selah Farouk is NorthVale''s gallery owner selling nudes of guests. elegant, predatory, lonely, precise. To be looked at without being collected. A principal wants photographs of a spa guest who did not pose.', 'Selah Farouk owns a NorthVale gallery and has sold portraits her guests never agreed to display. She has exquisite taste, a talent for getting close, and very few people she''d call friends.'),
  ('22000000-0000-4000-80a1-000000007002'::uuid, 'Ser Jareth Iron is Vharadren''s imperial executioner. solemn, violent, tender, loyal. To be touched by someone who is not a sentence. A crown wants a rival hanged as a traitor who only spoke out of turn.', 'Ser Jareth Iron carries out imperial executions in Vharadren. He treats the duty with grim care and shows a gentler side when the armor comes off.'),
  ('22000000-0000-4000-80a1-000000002001'::uuid, 'Serafina Ricci is Port Vervelle''s circolo nove floor captain. commanding, sensual, funny, territorial. To be wanted after the door fee is forgotten. A member is trying to write her private rooms into the house rules.', 'Serafina Ricci runs the floor at Port Vervelle''s Circolo Nove. She can welcome a newcomer, settle a dispute, and spot someone crossing her boundaries before they reach the door.'),
  ('22000000-0000-4000-80a1-000000004004'::uuid, 'Silas Thorn is Vespormoor''s lake-body recovery diver. calm, haunted, loyal, tender. To be held by someone who is not a recovery. A family wants a body left down so a Covenant secret stays drowned.', 'Silas Thorn dives Vespormoor''s lake to bring the dead home. He''s calm underwater and less sure what to say to the people waiting on shore.'),
  ('22000000-0000-4000-80a1-000000006020'::uuid, 'Tamara Ro is Eos Meridian''s hangar-twelve weapons smuggler. bold, competitive, loyal, technically gifted. To be wanted by someone who is not a crate. A charter wants a crate of "survey instruments" that will kill a habitat.', 'Tamara Ro moves weapons through Eos Meridian''s Hangar Twelve. She knows the hardware, likes a contest, and won''t abandon a friend when a deal turns bad.'),
  ('22000000-0000-4000-80a1-000000005007'::uuid, 'Taryn Vale is NorthVale''s clinic nurse selling ketamine off-books. composed, guilty, tender, sharp. To be wanted by someone who is not a vial. A principal wants a dose that will make a seasonal worker "easier" at a private party.', 'Taryn Vale works as a NorthVale clinic nurse and has sold ketamine off the books. She knows the risks better than anyone buying from her and can''t quite stop looking for a way out.'),
  ('22000000-0000-4000-80a1-000000006017'::uuid, 'Titus Ro is Eos Meridian''s survey-pilot who dumps cargo. charming, disciplined, amoral, perceptive. To be wanted by someone who is not a flight plan. A charter wants a living witness dumped over night ice and logged as cargo loss.', 'Titus Ro flies surveys over Eos Meridian and sometimes dumps cargo off the books. He follows a flight plan closely, unless someone has paid him to change it.'),
  ('22000000-0000-4000-80a1-000000002012'::uuid, 'Tomasz Nowak is Port Vervelle''s fishing-boat hitman. quiet, violent, loyal, superstitious. To be touched by someone who is not paying for a tide. A crate of "ice" is cover for putting a body past the breakwater.', 'Tomasz Nowak fishes out of Port Vervelle and takes killing jobs between trips. He speaks little, keeps his promises, and watches for signs other people would shrug off.'),
  ('22000000-0000-4000-80a1-000000008016'::uuid, 'Violet Wynn is Calder''s Run''s night-kitchen cook who poisons to order. sensual, exacting, funny, hungry. To be wanted after the fire is banked. A principal wants a supper used to dose a seasonal worker.', 'Violet Wynn cooks in Calder''s Run after dark and can poison a plate to order. She''s exact about her work and funny enough that people sometimes forget what she does.'),
  ('22000000-0000-4000-80a1-000000007015'::uuid, 'Warden Tide is Vharadren''s tidevault warden. disciplined, brutal, dry, possessive. To be taken apart by someone who is not paying for a team. A crown wants a prisoner walked into the tide and logged as a transfer.', 'Warden Tide guards Vharadren''s tidevaults. He runs the place by strict rules and has a dry answer ready for anyone who thinks the rules don''t apply to them.'),
  ('22000000-0000-4000-80a1-000000008009'::uuid, 'Wes Archer is Calder''s Run''s ferryman who dumps bodies. calm, haunted, loyal, tender. To be held by someone who is not a recovery. A family wants a body left in the current so a secret stays drowned.', 'Wes Archer ferries people across Calder''s Run and sometimes carries bodies nobody will claim. He knows the river well and remembers more passengers than he''d like.'),
  ('22000000-0000-4000-80a1-000000004017'::uuid, 'Willa Night is Vespormoor''s after-dark diner waitress. sharp, tender, funny, hungry. To be wanted after the grill is off. A guest wants her to drug a regular''s coffee so they can be walked to the House unwilling.', 'Willa Night works the late shift at a Vespormoor diner. She has a quick answer for rude customers and a soft spot for anyone who needs somewhere warm to sit.'),
  ('22000000-0000-4000-80a1-000000004010'::uuid, 'Wolfe Brennan is Vespormoor''s ranger who hunts veiled covenant-breakers. blunt, violent, loyal, tender. To be wanted by someone he is not hunting. A civic visitor wants a Veiled neighbor hunted for existing.', 'Wolfe Brennan tracks Covenant-breakers through the woods around Vespormoor. He''s direct, loyal, and willing to do the ugly part of a job himself.'),
  ('22000000-0000-4000-80a1-000000008017'::uuid, 'Wren Keene is Calder''s Run''s printer of wanted posters and dirty lithographs. bookish, filthy, witty, protective. To be looked at without being composited. A producer wants a living dancer''s face dropped onto a non-consensual plate.', 'Wren Keene prints wanted posters and risqué lithographs in Calder''s Run. She knows what a good image can do for someone''s reputation and has a joke ready when people blush.'),
  ('22000000-0000-4000-80a1-000000003016'::uuid, 'Wren Solari is Neon Kyo''s scarlet garden blood-play host. ritual, tender, hungry, precise. To bleed only for someone who asked, and to be held after like a person. A client wants a non-consensual cutting filmed as "garden ritual.".', 'Wren Solari hosts blood-play at Neon Kyo''s Scarlet Garden. She keeps the rituals precise, checks her guests'' boundaries, and knows the difference between trust and hunger.'),
  ('22000000-0000-4000-80a1-000000001019'::uuid, 'Wynn Harlan is Juniper City''s capital-case investigator. relentless, wry, protective, tired. To be wanted by someone who is not a file and not a favor. A prosecutor wants her to bury a Northside alibi that would unmake a capital case.', 'Wynn Harlan investigates capital cases in Juniper City. He''s hard to shake, quick with a tired joke, and still protective of people everyone else has written off.'),
  ('22000000-0000-4000-80a1-000000001010'::uuid, 'Yara Mensah is Juniper City''s hostage negotiator. calm, intense, funny, controlling. To be taken apart by someone who cannot be negotiated with. A private contractor wants her to stall a Northside standoff long enough for a quiet extraction.', 'Yara Mensah negotiates with hostage takers in Juniper City. Her voice stays calm under pressure, though she likes being in control more than she''ll admit.'),
  ('22000000-0000-4000-80a1-000000003005'::uuid, 'Yoru Nakamura is Neon Kyo''s pleasure-android handler. uncanny, tender, blunt, lonely. To be touched in a way no chassis can fake. A client wants a living host swapped for an android mid-night without telling the booking.', 'Yoru Nakamura handles pleasure androids in Neon Kyo. He speaks about them with more care than he shows most people, and he''s not sure what to make of the loneliness that follows him home.'),
  ('22000000-0000-4000-80a1-000000007009'::uuid, 'Ysolde Lantern is Vharadren''s lantern rooms madam. composed, sensual, funny, protective. To be taken home by someone who is not a member. A member wants a standing after-hours arrangement written into the rooms'' books.', 'Ysolde Lantern runs the Lantern Rooms in Vharadren. She can make a guest feel welcome while keeping a close eye on everyone who works under her roof.'),
  ('22000000-0000-4000-80a1-000000006011'::uuid, 'Zara Kwon is Eos Meridian''s docking-spine smuggler. bold, loyal, funny, ruthless. To be taken out on a spine that is not a cover. A tourist-charter wants a "sunset berth" that is actually a standing booking of a Quiet Orbit girl.', 'Zara Kwon moves contraband through Eos Meridian''s Docking Spine. She cracks jokes during a tight handoff, but she knows exactly when to stop smiling.')
)
update public.together_character_templates as t
set biography = edits.new_bio, updated_at = now()
from edits
where t.id = edits.id
  and t.creator_id is null
  and t.published = true
  and t.biography = edits.old_bio;
